{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.PHILIPS_AMAZON_VENDOR_PARTNER_SALES AS SELECT \'AMAZON VC\' AS marketplace, \'AMAZON VC\' AS CHANNEL, \'AMAZON VC\' AS SOURCE, CONCAT( a.Asin, CAST(startDate AS DATE), orderedUnits, CAST(PARSE_JSON(orderedRevenue):amount AS FLOAT), CAST(endDate AS DATE) ) AS ORDER_ID, CONCAT( a.Asin, CAST(startDate AS DATE), orderedUnits, CAST(PARSE_JSON(orderedRevenue):amount AS FLOAT), CAST(endDate AS DATE) ) AS reference_code, CONCAT( a.Asin, CAST(startDate AS DATE), orderedUnits, CAST(PARSE_JSON(orderedRevenue):amount AS FLOAT), CAST(endDate AS DATE) ) AS SALEORDERITEMCODE, CONCAT( a.Asin, CAST(startDate AS DATE), orderedUnits, CAST(PARSE_JSON(orderedRevenue):amount AS FLOAT), CAST(endDate AS DATE) ) AS SALES_ORDER_ITEM_ID, CAST(a.asin AS STRING) AS Asin, CAST(startDate AS TIMESTAMP) AS startTime, CAST(startDate AS date) as ordeR_Date, CAST(endDate AS TIMESTAMP) AS endTime, CAST(orderedUnits AS INTEGER) AS Ordered_Units, CAST(PARSE_JSON(orderedRevenue):amount AS FLOAT) AS Ordered_Revenue, CAST(shippedUnits AS INTEGER) AS ShippedUnits, CAST(customerReturns AS INTEGER) AS CustomerReturns, ( CAST(PARSE_JSON(orderedRevenue):amount AS FLOAT) / NULLIF(CAST(orderedUnits AS INTEGER), 0) ) * CAST(customerReturns AS INTEGER) AS returned_revenue, (shippedunits - customerreturns)*replace(c.MRP,\',\',\'\') selling_price, upper(b.product_name) AS PRODUCT_NAME, UPPER(b.CATEGORY) AS PRODUCT_CATEGORY, upper(b.sub_Category) as product_sub_category, b.primarykey as sku FROM (select * from maplemonk.philips_amazon_vendor_get_vendor_sales_report where CAST(startDate AS date) > (select max(DATEADD(DAY, date, \'1899-12-30\'::DATE)) from philips_db.MAPLEMONK.philips_s3_sales_historical_amazon) )a left join (select distinct ASN, primarykey, category, sub_category, \"PRODUCT TITLE\" product_name from PHILIPS_DB.MAPLEMONK.PHILIPS_GS_SKU_MASTER) b on CAST(a.asin AS STRING) = b.ASN left join ( select * from PHILIPS_DB.MAPLEMONK.PHILIPS_GS_SKU_MRP_COGS where lower(marketplace) = \'amazon\' ) c on upper(trim(b.primarykey)) = upper(trim(c.sku_code)) AND CAST(a.startDate AS DATE) BETWEEN c.start_date AND c.end_date union all select \'AMAZON VC\' AS marketplace, \'AMAZON VC\' AS CHANNEL, \'AMAZON VC\' AS SOURCE, null AS ORDER_ID, null as reference_code, null AS SALEORDERITEMCODE, null AS SALES_ORDER_ITEM_ID, Asin, DATEADD(DAY, date, \'1899-12-30\'::DATE) AS startTime, DATEADD(DAY, date, \'1899-12-30\'::DATE) as ordeR_Date, DATEADD(DAY, date, \'1899-12-30\'::DATE) AS endTime, null AS Ordered_Units, null AS Ordered_Revenue, CAST(\"Shipped Units\" AS INTEGER) AS ShippedUnits, CAST(\"Customer Returns\" AS INTEGER) AS CustomerReturns, null AS returned_revenue, value::float selling_price, upper(\"Product Title\") as product_name, upper(bu) as product_category, upper(sag) as product_sub_Category, ctn as sku from philips_db.maplemonk.philips_s3_sales_historical_amazon ;",
                    "transaction": true
                }
            ) }}
